glsl_fragment:
vec2 _tile_uv = UV * {{ inputs.uv_tile }};
vec2 _anim_uv = _tile_uv + vec2(
    sin(TIME * {{ inputs.scroll_speed }} + {{ inputs.world_pos }}.x * 0.18) * {{ inputs.scroll_amplitude }},
    cos(TIME * {{ inputs.scroll_speed }} * 0.73 + {{ inputs.world_pos }}.z * 0.18) * {{ inputs.scroll_amplitude }}
);
{% for b in inputs.biomes_list %}vec3 a_{{ b.name }} = texture(albedo_{{ b.name }}, {% if b.animate %}_anim_uv{% else %}_tile_uv{% endif %}).rgb;
{% endfor %}vec3 {{ outputs.albedo }} = ({% for b in inputs.biomes_list %}a_{{ b.name }} * w_{{ b.name }}{% if not loop.last %}
        + {% endif %}{% endfor %}) / {{ inputs.wsum }};
